create or replace function public.category_legacy_rejection_blockers_v16_2_6(p_category_id text,p_title text)
returns text[]
language sql
stable
security definer
set search_path=public
as $$
  with exact_matches as (
    select r.legacy_key,r.default_decision
    from public.legacy_category_rejections_v16_2_6 r
    where r.normalized_title=regexp_replace(lower(coalesce(p_title,'')),'[^a-z0-9]+','','g')
  ), semantic_alias_matches as (
    select r.legacy_key,
      case when a.review_status='confirmed_exclusion' then 'confirmed_exclusion' else 'requires_reaudit' end as default_decision
    from public.legacy_rejection_semantic_aliases_v16_2_6 a
    join public.legacy_category_rejections_v16_2_6 r on r.legacy_key=a.legacy_key
    where a.alias_normalized_title=regexp_replace(lower(coalesce(p_title,'')),'[^a-z0-9]+','','g')
      and a.review_status<>'cleared'
  ), linked_matches as (
    select r.legacy_key,r.default_decision
    from public.category_legacy_rejection_resolutions_v16_2_6 x
    join public.legacy_category_rejections_v16_2_6 r on r.legacy_key=x.legacy_key
    where x.category_id=p_category_id
  ), matches as (
    select * from exact_matches
    union select * from semantic_alias_matches
    union select * from linked_matches
  )
  select coalesce(array_agg(m.legacy_key order by m.legacy_key) filter(
    where coalesce(x.decision,m.default_decision)<>'cleared_for_reconsideration'
  ),'{}'::text[])
  from matches m
  left join public.category_legacy_rejection_resolutions_v16_2_6 x
    on x.category_id=p_category_id and x.legacy_key=m.legacy_key;
$$;
revoke all on function public.category_legacy_rejection_blockers_v16_2_6(text,text) from public,anon,authenticated;
grant execute on function public.category_legacy_rejection_blockers_v16_2_6(text,text) to service_role;

-- Append the guard to the existing runtime view without changing existing column order.
create or replace view public.category_runtime_review_v16_2
with(security_invoker=true) as
select
  v.*,
  a.proposed_status as promotion_decision_v16_2,
  a.reason as promotion_reason_v16_2,
  a.primary_blocker as primary_blocker_v16_2,
  a.blocker_class as blocker_class_v16_2,
  a.strict_pass as strict_pass_v16_2,
  a.source_quality_floor as source_quality_floor_v16_2,
  a.suggested_duplicate_of as suggested_duplicate_of_v16_2,
  (
    a.proposed_status='playable'
    and v.editorial_status='approved'
    and a.strict_pass
    and public.category_v16_2_6_hard_block_reason(c.id,c.source_organization,c.source_indicator_code,v.effective_title,c.metadata) is null
    and cardinality(legacy.blockers)=0
  ) as computed_playable_v16_2,
  array_remove(array[
    case when a.proposed_status<>'playable' then a.primary_blocker end,
    public.category_v16_2_6_hard_block_reason(c.id,c.source_organization,c.source_indicator_code,v.effective_title,c.metadata),
    case when cardinality(legacy.blockers)>0 then 'legacy_rejection_reaudit' end
  ],null) as v16_2_blockers,
  array_remove(array[
    case when v.validation_status<>'verified'
      and not public.category_v15_true_integrity_failure(
        v.validation_status,v.validation_reason,
        v.validation_mismatch_count,v.validation_ranking_mismatch_count
      ) then 'Official values are usable; non-data source metadata remain incomplete.' end,
    case when v.ranking_completeness_status='top_end_complete' then 'Ranking is top-end complete rather than fully comprehensive.' end,
    case when v.player_source_status='general' then 'Uses a general official source page rather than an exact shareable view.' end
  ],null) as v16_2_warnings,
  c.measurement_type,
  legacy.blockers as legacy_rejection_blockers_v16_2_6
from public.category_runtime_review_v16 v
join public.category_promotion_assessment_v16_2 a on a.category_id=v.id
join public.stat_categories c on c.id=v.id
cross join lateral (
  select public.category_legacy_rejection_blockers_v16_2_6(c.id,v.effective_title) as blockers
) legacy;
revoke all on public.category_runtime_review_v16_2 from public,anon,authenticated;
grant select on public.category_runtime_review_v16_2 to service_role;

drop view if exists public.category_review_workbench_v16_2;
create view public.category_review_workbench_v16_2
with(security_invoker=true) as
select runtime.*,
 vetting.recommendation as auto_vetting_recommendation,
 vetting.vetting_score as auto_vetting_score,
 vetting.reason as auto_vetting_reason,
 vetting.possible_duplicate_of as auto_possible_duplicate_of,
 vetting.title_similarity as auto_title_similarity,
 vetting.rank_correlation as auto_rank_correlation,
 vetting.tie_share as auto_tie_share,
 vetting.vetting_version as auto_vetting_version,
 vetting.vetted_at as auto_vetted_at
from public.category_runtime_review_v16_2 runtime
left join public.category_auto_vetting_v16 vetting on vetting.category_id=runtime.id;
revoke all on public.category_review_workbench_v16_2 from public,anon,authenticated;
grant select on public.category_review_workbench_v16_2 to service_role;

-- Any exact-title collision or explicitly linked semantic/source collision now
-- fails closed unless a reviewed resolution explicitly clears reconsideration.
update public.stat_categories c
set enabled=false,eligible_daily=false,updated_at=now()
from public.category_runtime_review_v16_2 v
where v.id=c.id and cardinality(v.legacy_rejection_blockers_v16_2_6)>0;

commit;

-- ===== v16.2.6 priority-150 legacy re-audit (migration 050) =====
-- geostats-v16.2.6-priority-150-legacy-reaudit
-- First-principles review of the highest-priority generic non-FAOSTAT legacy rejections.
-- Clearing a legacy block does NOT make a category playable; all source, integrity, duplication, editorial and activation gates still apply.
begin;

alter table public.legacy_category_rejections_v16_2_6 drop constraint if exists legacy_category_rejections_v16_2_6_default_decision_check;
alter table public.legacy_category_rejections_v16_2_6 add constraint legacy_category_rejections_v16_2_6_default_decision_check check(default_decision in ('requires_reaudit','cleared_for_reconsideration','confirmed_exclusion'));

create table if not exists public.legacy_rejection_first_principles_reaudit_v16_2_6 (
  legacy_key text primary key references public.legacy_category_rejections_v16_2_6(legacy_key) on delete cascade,
  source_line integer not null unique,
  category_title text not null,
  legacy_source text not null,
  legacy_domain_series text,
  historical_integrity_status text,
  historical_quality text,
  editorial_disposition text not null check(editorial_disposition in ('advance_to_validation','clear_legacy_block_current_path_governs','hold_for_family_curation','retain_exclusion')),
  legacy_guard_action text not null check(legacy_guard_action in ('clear_generic_legacy_block','keep_reaudit_block','confirm_reasoned_exclusion')),
  reason_class text not null,
  first_principles_rationale text not null,
  recommended_next_action text not null,
  linked_tracker_ids text,
  linked_tracker_dispositions text,
  reviewed_at timestamptz not null default now()
);
alter table public.legacy_rejection_first_principles_reaudit_v16_2_6 enable row level security;
revoke all on public.legacy_rejection_first_principles_reaudit_v16_2_6 from public,anon,authenticated;
grant select,insert,update,delete on public.legacy_rejection_first_principles_reaudit_v16_2_6 to service_role;

insert into public.legacy_rejection_first_principles_reaudit_v16_2_6(legacy_key,source_line,category_title,legacy_source,legacy_domain_series,historical_integrity_status,historical_quality,editorial_disposition,legacy_guard_action,reason_class,first_principles_rationale,recommended_next_action,linked_tracker_ids,linked_tracker_dispositions) values
  ('legacy:589',589,'Most asylum seekers originating','UNHCR','Displacement · population:coo:asylum_seekers','verified','95','advance_to_validation','clear_generic_legacy_block','broad_intuitive_distinct','Broad, recognizable displacement measure with a distinct player-facing question; the old generic rejection is not a sufficient reason to suppress it.','Use the recovered UNHCR Refugee Data Finder importer; validate coverage/year consistency and then clear the legacy-only blocker.','family:unhcr:most-asylum-seekers-originating','ready_for_source_family_validation'),
  ('legacy:600',600,'Lowest upper-secondary out-of-school rate','UNESCO UIS','Education · ROFST.MOD.3','verified','94','advance_to_validation','clear_generic_legacy_block','broad_intuitive_distinct','Out-of-school rates are intuitive, globally meaningful education-access measures; primary and upper-secondary provide meaningfully different stages without keeping every adjacent stage.','Validate the UNESCO UIS source-family rows and retain only these stage anchors unless later playtesting supports more.','family:unesco:lowest-upper-secondary-out-of-school','ready_for_source_family_validation'),
  ('legacy:601',601,'Lowest lower-secondary out-of-school rate','UNESCO UIS','Education · ROFST.MOD.2','verified','94','hold_for_family_curation','keep_reaudit_block','family_density_near_duplicate','Plausible in isolation, but too close to a stronger retained stage/subject/infrastructure anchor or part of an over-dense education family; needs family-level curation before any legacy block is cleared.','Keep quarantined; compare against the selected UNESCO anchors and only promote if it adds a clearly different player experience.','family:unesco:lowest-lower-secondary-out-of-school','ready_for_source_family_validation'),
  ('legacy:606',606,'Highest primary-school completion rate','UNESCO UIS','Education · CR.MOD.1','','94','hold_for_family_curation','keep_reaudit_block','family_density_near_duplicate','Plausible in isolation, but too close to a stronger retained stage/subject/infrastructure anchor or part of an over-dense education family; needs family-level curation before any legacy block is cleared.','Keep quarantined; compare against the selected UNESCO anchors and only promote if it adds a clearly different player experience.','',''),
  ('legacy:607',607,'Highest upper-secondary completion rate','UNESCO UIS','Education · CR.MOD.3','','94','advance_to_validation','clear_generic_legacy_block','broad_intuitive_distinct','Upper-secondary completion is a recognizable education outcome and is more discriminating than another near-universal primary enrollment measure.','Resolve the exact UIS completion series in the importer, validate coverage, and use a plain-English title/definition.','',''),
